#include "functions8.h"

int main(void) {
    char *result = NULL;
    status_code status;

    // 199 + 27 в 10й
    status = sum_in_base(&result, 10, 2, "199", "27");
    print_sum(status, result);
    free(result);
    result = NULL;

    // FF + 1 + A в 16й
    status = sum_in_base(&result, 16, 3, "FF", "1", "A");
    print_sum(status, result);
    free(result);
    result = NULL;

    // 111 + 1 в 2й
    status = sum_in_base(&result, 2, 2, "111", "1");
    print_sum(status, result);
    free(result);
    result = NULL;

    // z + 1 в 36й
    status = sum_in_base(&result, 3, 2, "Z", "1");
    print_sum(status, result);
    free(result);
    result = NULL;

    // большие числа в 10й
    status = sum_in_base(&result, 10, 2,
                         "1",
                         "");
    print_sum(status, result);
    free(result);
    result = NULL;

    // нули
    status = sum_in_base(&result, 10, 2, "0", "0");
    print_sum(status, result);
    free(result);
    result = NULL;

    // одно число
    status = sum_in_base(&result, 10, 1, "00012");
    print_sum(status, result);
    free(result);
    result = NULL;

    // нет чисел
    status = sum_in_base(&result, 10, 0);
    print_sum(status, result);
    free(result);
    result = NULL;

    // основание 37
    status = sum_in_base(&result, 37, 1, "1");
    print_sum(status, result);
    free(result);
    result = NULL;

    // цифра больше основания
    status = sum_in_base(&result, 8, 2, "19", "1");
    print_sum(status, result);
    free(result);
    result = NULL;

    // строчные буквы
    status = sum_in_base(&result, 16, 1, "ff");
    print_sum(status, result);
    free(result);
    result = NULL;

    // пустая строка
    status = sum_in_base(&result, 10, 2, "5", "");
    print_sum(status, result);
    free(result);
    result = NULL;

    return SUCCESS;
}